/** Interpolate along snapped path — cùng nét L.Polyline, không nearest toàn cục. */

const EARTH_KM = 6371;

function haversineKm(a: [number, number], b: [number, number]): number {
  const toRad = (d: number) => (d * Math.PI) / 180;
  const dLat = toRad(b[0] - a[0]);
  const dLng = toRad(b[1] - a[1]);
  const h =
    Math.sin(dLat / 2) ** 2 +
    Math.cos(toRad(a[0])) * Math.cos(toRad(b[0])) * Math.sin(dLng / 2) ** 2;
  return 2 * EARTH_KM * Math.asin(Math.min(1, Math.sqrt(h)));
}

export function pathLengthKm(path: [number, number][]): number {
  let n = 0;
  for (let i = 1; i < path.length; i += 1) n += haversineKm(path[i - 1], path[i]);
  return n;
}

function cumKm(path: [number, number][]): number[] {
  const d = [0];
  for (let i = 1; i < path.length; i += 1) {
    d.push(d[i - 1] + haversineKm(path[i - 1], path[i]));
  }
  return d;
}

export function interpolatePath(path: [number, number][], t: number): [number, number] {
  if (path.length === 0) return [0, 0];
  if (path.length === 1 || t <= 0) return path[0];
  if (t >= 1) return path[path.length - 1];
  const dist = cumKm(path);
  const total = dist[dist.length - 1];
  if (total < 1e-9) return path[0];
  const target = t * total;
  let i = 1;
  while (i < dist.length && dist[i] < target) i += 1;
  const a = path[i - 1];
  const b = path[i] || a;
  const span = dist[i] - dist[i - 1];
  const f = span < 1e-12 ? 0 : (target - dist[i - 1]) / span;
  return [a[0] + (b[0] - a[0]) * f, a[1] + (b[1] - a[1]) * f];
}

export type LayerPt = { x: number; y: number };

type MapProjector = {
  latLngToLayerPoint: (latlng: [number, number]) => LayerPt;
  layerPointToLatLng: (point: LayerPt) => { lat: number; lng: number };
};

export function asMapProjector(map: L.Map): MapProjector | null {
  const m = map as unknown as Partial<MapProjector>;
  if (typeof m.latLngToLayerPoint !== 'function' || typeof m.layerPointToLatLng !== 'function') {
    return null;
  }
  return m as MapProjector;
}

function hypot(a: LayerPt, b: LayerPt): number {
  return Math.hypot(b.x - a.x, b.y - a.y);
}

function lerpPt(a: LayerPt, b: LayerPt, f: number): LayerPt {
  return { x: a.x + (b.x - a.x) * f, y: a.y + (b.y - a.y) * f };
}

/** Điểm pixel trên nét vẽ (cùng phép với SVG polyline). */
export function interpolateLayerPoint(
  proj: MapProjector,
  path: [number, number][],
  t: number,
): LayerPt {
  const pts = path.map((ll) => proj.latLngToLayerPoint(ll));
  if (!pts.length) return { x: 0, y: 0 };
  if (pts.length === 1 || t <= 0) return pts[0];
  if (t >= 1) return pts[pts.length - 1];
  const dist = [0];
  for (let i = 1; i < pts.length; i += 1) dist.push(dist[i - 1] + hypot(pts[i - 1], pts[i]));
  const total = dist[dist.length - 1];
  if (total < 1e-6) return pts[0];
  const target = t * total;
  let i = 1;
  while (i < dist.length && dist[i] < target) i += 1;
  const span = dist[i] - dist[i - 1];
  const f = span < 1e-9 ? 0 : (target - dist[i - 1]) / span;
  return lerpPt(pts[i - 1], pts[i], f);
}

export function headingDegOnLayer(
  proj: MapProjector,
  path: [number, number][],
  t: number,
): number {
  if (path.length < 2) return 0;
  const look = 0.003;
  const a = interpolateLayerPoint(proj, path, Math.max(0, t - look));
  const b = interpolateLayerPoint(proj, path, Math.min(1, t + look));
  return (Math.atan2(b.x - a.x, -(b.y - a.y)) * 180) / Math.PI;
}

export function headingDeg(path: [number, number][], t: number): number {
  if (path.length < 2) return 0;
  const look = 0.004;
  const a = interpolatePath(path, Math.max(0, t - look));
  const b = interpolatePath(path, Math.min(1, t + look));
  return (Math.atan2(b[1] - a[1], b[0] - a[0]) * 180) / Math.PI;
}

/** Duration ms — ~8s/km, clamp 14–42s. */
export function animDurationMs(path: [number, number][]): number {
  const km = pathLengthKm(path);
  return Math.min(42000, Math.max(14000, km * 8000));
}
