import type { CheckInStopKind } from '../../shared/map/mapCheckInPin';

export type StopKind = CheckInStopKind;

export type PatrolStopView = {
  id: string;
  planPointLabel: string;
  route: string;
  lat: number;
  lng: number;
  createdAt: string | null;
  pending: boolean;
  kind?: StopKind;
};

export function kmSortKey(label: string): number {
  const plus = String(label).match(/(\d+)\+(\d+)/);
  if (plus) return Number(plus[1]) * 1000 + Number(plus[2]);
  const km = String(label).match(/Km\s*(\d+)/i);
  return km ? Number(km[1]) * 1000 : 0;
}

