function nearStop(
  a: { lat: number; lng: number },
  b: { lat: number; lng: number },
): boolean {
  const dLat = a.lat - b.lat;
  const dLng = a.lng - b.lng;
  return dLat * dLat + dLng * dLng < 0.0007 * 0.0007;
}

export function mergePatrolStops(
  checks: PatrolCheckInDto[],
  sessionId: string,
): PatrolStopView[] {
  const out: PatrolStopView[] = (checks || [])
    .filter((c) => Number.isFinite(c.lat) && Number.isFinite(c.lng))
    .map((c) => ({
      id: c.id,
      planPointLabel: c.planPointLabel,
      route: c.route,
      lat: c.lat,
      lng: c.lng,
      createdAt: c.createdAt,
      pending: false,
    }));
  for (const p of FALLBACK_PLAN[sessionId] ?? []) {
    if (out.some((s) => nearStop(s, p))) continue;
    out.push({ ...p, createdAt: null, pending: true });
  }
  out.sort((a, b) => kmSortKey(a.planPointLabel) - kmSortKey(b.planPointLabel));
  return annotateStopKinds(out);
}

export function annotateStopKinds(stops: PatrolStopView[]): PatrolStopView[] {
  const lastDone = stops.reduce((acc, s, i) => (s.pending ? acc : i), -1);
  return stops.map((s, i) => {
    if (!s.pending) return { ...s, kind: 'done' as const };
    if (lastDone > i) return { ...s, kind: 'skipped' as const };
    return { ...s, kind: 'pending' as const };
  });
}

/** Index pin đã check-in cuối (−1 nếu chưa có). Điểm bỏ qua giữa đường vẫn nằm trên {RidePath}. */
export function lastCompletedStopIndex(stops: PatrolStopView[]): number {
  let last = -1;
  for (let i = 0; i < stops.length; i += 1) {
    if (!stops[i].pending) last = i;
  }
  return last;
}

export function pathFromStops(stops: PatrolStopView[]): [number, number][] {
  const pts = stops
    .filter((s) => Number.isFinite(s.lat) && Number.isFinite(s.lng))
    .map((s) => [s.lat, s.lng] as [number, number]);
  if (pts.length >= 2) return pts;
  if (pts.length === 1) return [pts[0], QL1_VINH_WAYPOINTS[QL1_VINH_WAYPOINTS.length - 1]];
  return QL1_VINH_WAYPOINTS;
}

export function pathFromCheckIns(items: PatrolCheckInDto[]): [number, number][] {
  return pathFromStops(
    (items || []).map((c) => ({
      id: c.id,
      planPointLabel: c.planPointLabel,
      route: c.route,
      lat: c.lat,
      lng: c.lng,
      createdAt: c.createdAt,
      pending: false,
    })),
  );
}
