import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { resetLeafletContainer, useLeaflet } from '../../demo/useLeaflet';
import { patrolService } from '../../services/patrol/patrolService';
import type { PatrolCheckInDto, PatrolDto } from '../../services/patrol/responseModel';
import {
  MapViewToggleIcon,
  GisMapSideTabs,
  useGisSideDock,
  applyClipBasemapStyle,
  attachVnClipBasemap,
  CLIP_STYLE_OPTIONS,
  VN_CLIP_MIN_ZOOM,
  vnLeafletMapOptions,
  ensureLinePanes,
  ensureOsrmLineIndex,
  lookupOsrmPathsByRouteKey,
  routeKmChainAlongHighway,
  routeHighwayLegs,
  walkPathThroughStops,
  concatPathSegments,
  projectToPath,
  isSparseGpsChord,
  longestOpenPath,
  addCheckInMarker,
  checkInKindOf,
  checkInStatusLabel,
  LINE_PANES,
  type ClipStyleKind,
  type GisPatrolSideTabId,
} from '../../shared/map';
import {
  MY_LOCATION_LABEL,
  MY_LOCATION_TITLE,
  locateUserOnMap,
  type MyLocationHold,
} from '../../shared/map/locateUserOnMap';
import {
  interpolatePath,
  animDurationMs,
} from './animateAlongPath';
import {
  FALLBACK_CHECKINS,
  FALLBACK_SESSIONS,
  mergePatrolStops,
  pathFromStops,
  lastCompletedStopIndex,
  kmSortKey,
  QL1_VINH_WAYPOINTS,
  VINH_FIT_BOUNDS,
  type PatrolStopView,
} from './vinhPatrolSeed';
import live from '../GisDrawLivePage/GisDrawLivePage.module.css';
import styles from './GisPatrolMapPage.module.css';
import '../../shared/map/gisMapStack.css';

const PATROL_TABS: ReadonlyArray<readonly [GisPatrolSideTabId, string]> = [
  ['tuan-duong', 'Tuần đường'],
  ['tuan-kiem', 'Tuần kiểm'],
  ['chi-tiet', 'Chi tiết'],
];

const COLOR_TD = '#0C84C0';
const COLOR_TK = '#c2410c';

type PersonRow = {
  userName: string;
  jobTitle: string;
  patrolType: string;
  sessions: PatrolDto[];
  routes: string[];
  status: string;
  coverage: number;
};

function jobTitleOf(s: PatrolDto): string {
  if (s.jobTitle) return s.jobTitle;
  if (s.userName.includes('Tuấn')) return 'Tổ trưởng tuần kiểm';
  if (s.userName.includes('Thị B')) return 'Nhân viên tuần đường';
  return s.patrolType === 'Tuần kiểm' ? 'Cán bộ tuần kiểm' : 'Cán bộ tuần đường';
}

function personLineColor(userName: string, patrolType: string): string {
  if (userName.includes('Thị B')) return '#0f766e';
  if (userName.includes('Tuấn')) return '#7c3aed';
  return patrolType === 'Tuần kiểm' ? COLOR_TK : COLOR_TD;
}

function riderIconHtml(color: string, selected: boolean): string {
  const size = selected ? 36 : 28;
  return `<div data-rider style="width:${size}px;height:${size}px;line-height:0">
    <svg viewBox="0 0 32 32" width="${size}" height="${size}" aria-hidden="true" style="display:block">
      <circle cx="16" cy="16" r="14" fill="${color}" opacity="${selected ? 0.95 : 0.82}" stroke="#fff" stroke-width="2"/>
      <circle cx="16" cy="11" r="4" fill="#fff"/>
      <path d="M10 22 C12 16 20 16 22 22" fill="none" stroke="#fff" stroke-width="2" stroke-linecap="round"/>
    </svg>
  </div>`;
}

function riderDivIcon(L: typeof window.L, color: string, selected: boolean): L.DivIcon {
  const size = selected ? 36 : 28;
  const half = size / 2;
  return L.divIcon({
    className: 'leaflet-div-icon ci-rider-icon',
    html: riderIconHtml(color, selected),
    iconSize: [size, size],
    iconAnchor: [half, half],
  });
}

function ensurePatrolPinStyles(): void {
  if (typeof document === 'undefined') return;
  const id = 'rmms-patrol-rider-v1';
  let el = document.getElementById(id);
  if (!el) {
    el = document.createElement('style');
    el.id = id;
    document.head.appendChild(el);
  }
  el.textContent = `
.leaflet-marker-icon.ci-rider-icon,
.leaflet-div-icon.ci-rider-icon {
  background: transparent !important;
  border: 0 !important;
  padding: 0 !important;
  line-height: 0 !important;
  overflow: visible !important;
  box-sizing: border-box !important;
}
.leaflet-marker-icon.ci-rider-icon [data-rider],
.leaflet-marker-icon.ci-rider-icon svg {
  display: block !important;
  line-height: 0 !important;
}
`;
}

function pickIndexedPath(
  paths: [number, number][][],
  raw: [number, number][],
): [number, number][] | null {
  const seed = raw[0];
  if (!seed) return null;
  let best: [number, number][] | null = null;
  let bestD = 0.05 * 0.05;
  for (const path of paths) {
    if (path.length < 2) continue;
    const p = projectToPath(seed[0], seed[1], path);
    const d = (p[0] - seed[0]) ** 2 + (p[1] - seed[1]) ** 2;
    if (d < bestD) {
      bestD = d;
      best = path;
    }
  }
  return best;
}

async function snapPatrolTrack(
  raw: [number, number][],
  routeKey: string,
): Promise<{ path: [number, number][]; dashed: boolean }> {
  if (raw.length < 2) return { path: [], dashed: true };
  const accept = (corridor: [number, number][] | null | undefined): [number, number][] | null => {
    if (!corridor || corridor.length < 2 || isSparseGpsChord(corridor)) return null;
    const open = longestOpenPath(corridor);
    if (open.length < 2 || isSparseGpsChord(open)) return null;
    const pinned = raw.map(([lat, lng]) => projectToPath(lat, lng, open));
    const walked = walkPathThroughStops(open, pinned);
    if (walked.length >= 2 && !isSparseGpsChord(walked)) return walked;
    return open.length > raw.length * 4 ? open : null;
  };
  await ensureOsrmLineIndex();
  const indexed = pickIndexedPath(lookupOsrmPathsByRouteKey(routeKey), raw);
  const fromIdx = accept(indexed);
  if (fromIdx) return { path: fromIdx, dashed: false };
  try {
    const hwy = await routeKmChainAlongHighway(raw, routeKey);
    const fromHwy = accept(hwy.path);
    if (fromHwy) return { path: fromHwy, dashed: false };
  } catch {
    /* legs */
  }
  const tryLegs = async (pts: [number, number][]) => {
    if (pts.length < 2) return null;
    try {
      const legs = await routeHighwayLegs(pts);
      return accept(legs) || (!isSparseGpsChord(legs) ? legs : null);
    } catch {
      return null;
    }
  };
  const fromAll = await tryLegs(raw);
  if (fromAll) return { path: fromAll, dashed: false };
  const fromEnds = await tryLegs([raw[0], raw[raw.length - 1]]);
  if (fromEnds) return { path: fromEnds, dashed: false };
  return { path: [], dashed: true };
}

function formatWhen(iso: string): string {
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return iso;
  return d.toLocaleString('vi-VN', { hour12: false });
}

function groupPeople(sessions: PatrolDto[], patrolType: string): PersonRow[] {
  const map = new Map<string, PatrolDto[]>();
  for (const s of sessions) {
    if (s.patrolType !== patrolType) continue;
    const arr = map.get(s.userName) ?? [];
    arr.push(s);
    map.set(s.userName, arr);
  }
  return [...map.entries()].map(([userName, items]) => ({
    userName,
    jobTitle: jobTitleOf(items[0]),
    patrolType,
    sessions: items,
    routes: [...new Set(items.map((i) => i.route))],
    status: items.find((i) => i.status === 'Đang tuần')?.status ?? items[0]?.status ?? '',
    coverage: Math.max(0, ...items.map((i) => i.coveragePercent)),
  }));
}

function activeSession(row: PersonRow): PatrolDto | undefined {
  return row.sessions.find((s) => s.status === 'Đang tuần') ?? row.sessions[0];
}

const GisPatrolMapPage: React.FC = () => {
  const { ready, error: leafletError } = useLeaflet();
  const mapRef = useRef<HTMLDivElement>(null);
  const mapInstanceRef = useRef<L.Map | null>(null);
  const clipLayerRef = useRef<L.Layer | null>(null);
  const trackLayerRef = useRef<L.FeatureGroup | null>(null);
  const peopleLayerRef = useRef<L.FeatureGroup | null>(null);
  const riderRef = useRef<L.Marker | null>(null);
  const rafRef = useRef(0);
  const myLocationHoldRef = useRef<MyLocationHold>({ group: null });
  const checkInsRef = useRef<Record<string, PatrolCheckInDto[]>>({});
  const snappedBySessionRef = useRef<Record<string, { path: [number, number][]; dashed: boolean }>>({});

  const [viewFull, setViewFull] = useState(false);
  const [clipStyle, setClipStyle] = useState<ClipStyleKind>('default');
  const [locating, setLocating] = useState(false);
  const [overlayStatus, setOverlayStatus] = useState('idle');
  const { sideTab, setSideTab, onTabClick, sideBodyOpen, toggleBody, stacked } =
    useGisSideDock('tuan-duong');
  const [sessions, setSessions] = useState<PatrolDto[]>(FALLBACK_SESSIONS);
  const [checkIns, setCheckIns] = useState<Record<string, PatrolCheckInDto[]>>(
    FALLBACK_CHECKINS,
  );
  const [selectedKey, setSelectedKey] = useState<string | null>(null);
  const [mapEpoch, setMapEpoch] = useState(0);

  checkInsRef.current = checkIns;

  const listType = sideTab === 'tuan-kiem' ? 'Tuần kiểm' : 'Tuần đường';
  const people = useMemo(
    () => groupPeople(sessions, listType),
    [sessions, listType],
  );
  const selected = useMemo(() => {
    const all = [
      ...groupPeople(sessions, 'Tuần đường'),
      ...groupPeople(sessions, 'Tuần kiểm'),
    ];
    return all.find((p) => `${p.patrolType}|${p.userName}` === selectedKey) ?? null;
  }, [sessions, selectedKey]);

  const locateMe = useCallback(() => {
    const map = mapInstanceRef.current;
    const Lf = window.L;
    if (!map || !Lf) return;
    setLocating(true);
    setOverlayStatus('Đang lấy vị trí…');
    void locateUserOnMap(map, Lf, myLocationHoldRef.current)
      .catch((err: unknown) => {
        setOverlayStatus(err instanceof Error ? err.message : 'Không lấy được vị trí');
      })
      .finally(() => setLocating(false));
  }, []);

  const selectPerson = useCallback(
    (row: PersonRow) => {
      setSelectedKey(`${row.patrolType}|${row.userName}`);
      setSideTab('chi-tiet');
    },
    [setSideTab],
  );

  useEffect(() => {
    const t = window.setTimeout(() => {
      const host = document.querySelector('[data-gis-map-page]');
      if (host) window.dispatchEvent(new Event('resize'));
    }, 0);
    return () => window.clearTimeout(t);
  }, [viewFull, sideBodyOpen, stacked]);

  useEffect(() => {
    const timer = window.setTimeout(() => {
      void (async () => {
        try {
          const page = await patrolService.getList({ page: 1, pageSize: 200 });
          if (page.items.length) {
            setSessions(page.items);
            const next: Record<string, PatrolCheckInDto[]> = {};
            await Promise.all(
              page.items.map(async (s) => {
                try {
                  const items = await patrolService.getCheckIns(s.id);
                  next[s.id] = items;
                } catch {
                  next[s.id] = FALLBACK_CHECKINS[s.id] ?? [];
                }
              }),
            );
            setCheckIns(next);
            setOverlayStatus(`${page.items.length} phiên tuần`);
          } else {
            setOverlayStatus('Seed Vinh · Nghệ An (chưa có API)');
          }
        } catch {
          setSessions(FALLBACK_SESSIONS);
          setCheckIns(FALLBACK_CHECKINS);
          setOverlayStatus('Seed Vinh · Nghệ An');
        }
      })();
    }, 0);
    return () => window.clearTimeout(timer);
  }, []);

  useEffect(() => {
    if (!ready || !mapRef.current) return undefined;
    const L = window.L;
    if (!L?.map) return undefined;
    const el = mapRef.current;
    let map: L.Map | null = null;
    const timer = window.setTimeout(() => {
      if (mapInstanceRef.current) {
        try {
          mapInstanceRef.current.remove();
        } catch {
          /* HMR */
        }
        mapInstanceRef.current = null;
      }
      resetLeafletContainer(el);
      try {
        map = L.map(el, vnLeafletMapOptions({ center: QL1_VINH_WAYPOINTS[2], zoom: 12 }));
      } catch {
        resetLeafletContainer(el);
        map = L.map(el, vnLeafletMapOptions({ center: QL1_VINH_WAYPOINTS[2], zoom: 12 }));
      }
      try {
        clipLayerRef.current = attachVnClipBasemap(map, clipStyle);
      } catch (clipErr) {
        setOverlayStatus(
          clipErr instanceof Error ? clipErr.message : 'Không gắn nền clip BFF',
        );
        return;
      }
      ensureLinePanes(map);
      trackLayerRef.current = new L.FeatureGroup().addTo(map);
      peopleLayerRef.current = new L.FeatureGroup().addTo(map);
      mapInstanceRef.current = map;
      map.fitBounds(VINH_FIT_BOUNDS, { padding: [36, 36], maxZoom: 13 });
      map.setMinZoom?.(VN_CLIP_MIN_ZOOM);
      setMapEpoch((n) => n + 1);
    }, 0);

    return () => {
      window.clearTimeout(timer);
      window.cancelAnimationFrame(rafRef.current);
      try {
        map?.remove();
      } catch {
        /* gone */
      }
      mapInstanceRef.current = null;
      clipLayerRef.current = null;
      trackLayerRef.current = null;
      peopleLayerRef.current = null;
      riderRef.current = null;
      myLocationHoldRef.current.group = null;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps -- init once when Leaflet ready
  }, [ready]);

  useEffect(() => {
    const map = mapInstanceRef.current;
    const L = window.L;
    const tracks = trackLayerRef.current;
    const peopleLayer = peopleLayerRef.current;
    if (!map || !L || !tracks || !peopleLayer) return undefined;

    let cancelled = false;
    window.cancelAnimationFrame(rafRef.current);
    tracks.clearLayers();
    peopleLayer.clearLayers();
    riderRef.current = null;
    ensurePatrolPinStyles();

    const rows =
      sideTab === 'chi-tiet' && selected
        ? [selected]
        : people;

    const timer = window.setTimeout(() => {
      void (async () => {
        setOverlayStatus('Đang gắn nét tuyến chính…');
        const snappedFor: {
          row: PersonRow;
          sess: PatrolDto;
          path: [number, number][];
          ridePath: [number, number][];
          stops: PatrolStopView[];
          pinLL: [number, number][];
          dashed: boolean;
        }[] = [];
        for (const row of rows) {
          const sess = activeSession(row);
          if (!sess) continue;
          const checks = checkInsRef.current[sess.id] ?? [];
          const stops = mergePatrolStops(checks, sess.id);
          const raw = pathFromStops(stops);
          const cacheKey = `hwy4:${sess.route}:${sess.id}:${raw.length}:${raw.map((p) => `${p[0].toFixed(5)},${p[1].toFixed(5)}`).join(';')}`;
          let packed = snappedBySessionRef.current[cacheKey];
          if (!packed) {
            packed = raw.length >= 2
              ? await snapPatrolTrack(raw, sess.route)
              : { path: [], dashed: true };
            snappedBySessionRef.current[cacheKey] = packed;
          }
          if (cancelled) return;
          const corridor = packed.path.length >= 2 ? packed.path : [];
          const pinLL = stops.map((s) =>
            corridor.length >= 2
              ? projectToPath(s.lat, s.lng, corridor)
              : [s.lat, s.lng] as [number, number],
          );
          const lastRide = lastCompletedStopIndex(stops);
          const segs: [number, number][][] = [];
          const drawPins = lastRide >= 0 ? pinLL.slice(0, lastRide + 1) : [];
          if (corridor.length >= 2 && drawPins.length >= 2) {
            for (let i = 0; i < drawPins.length - 1; i += 1) {
              const seg = walkPathThroughStops(corridor, [drawPins[i], drawPins[i + 1]]);
              if (seg.length >= 2 && !isSparseGpsChord(seg)) segs.push(seg);
            }
          }
          const track = longestOpenPath(segs.length ? concatPathSegments(segs) : []);
          const ridePath =
            drawPins.length >= 2 && corridor.length >= 2
              ? walkPathThroughStops(corridor, drawPins)
              : drawPins.slice(-1);
          snappedFor.push({
            row,
            sess,
            path: track,
            ridePath: ridePath.length ? ridePath : track,
            stops,
            pinLL,
            dashed: packed.dashed,
          });
        }
        if (cancelled) return;

        const trackPane = LINE_PANES.track.name;
        for (const { row, sess, path, ridePath, stops, pinLL, dashed } of snappedFor) {
          const isSel = selectedKey === `${row.patrolType}|${row.userName}`;
          const rowColor = personLineColor(row.userName, row.patrolType);
          if (path.length >= 2) {
            tracks.addLayer(
              L.polyline(path, {
                color: '#0f172a',
                weight: isSel ? 8 : 6,
                opacity: 0.22,
                pane: trackPane,
                lineJoin: 'round',
                lineCap: 'round',
                smoothFactor: 0,
              }),
            );
            tracks.addLayer(
              L.polyline(path, {
                color: rowColor,
                weight: isSel ? 5 : 3.5,
                opacity: isSel ? 0.95 : 0.7,
                pane: trackPane,
                lineJoin: 'round',
                lineCap: 'round',
                smoothFactor: 0,
                dashArray: dashed ? '8 10' : undefined,
              }),
            );
          }

          stops.forEach((stop, i) => {
            const kind = checkInKindOf(stop);
            addCheckInMarker(L, peopleLayer, {
              n: i + 1,
              kind,
              latlng: pinLL[i] || [stop.lat, stop.lng],
              personName: row.userName,
              jobTitle: row.jobTitle,
              placeName: stop.planPointLabel,
              route: stop.route || sess.route,
              lat: stop.lat,
              lng: stop.lng,
              snapped: !dashed,
              checkedAt: stop.createdAt,
            });
          });

          const lastRide = lastCompletedStopIndex(stops);
          const endPt =
            ridePath[ridePath.length - 1] ||
            (lastRide >= 0 ? pinLL[lastRide] : undefined) ||
            path[0];
          if (!endPt) continue;
          if (isSel || (snappedFor.length === 1 && ridePath.length)) {
            const startPt = ridePath[0] || endPt;
            const rider = L.marker(startPt, {
              icon: riderDivIcon(L, rowColor, true),
              zIndexOffset: 900,
              keyboard: false,
            });
            peopleLayer.addLayer(rider);
            rider.on?.('click', () => selectPerson(row));
            riderRef.current = rider;
          } else {
            const pinR = L.marker(endPt, {
              icon: riderDivIcon(L, rowColor, false),
              zIndexOffset: 700,
              keyboard: false,
            });
            peopleLayer.addLayer(pinR);
            pinR.on?.('click', () => selectPerson(row));
          }
        }

        const run = selected ?? (rows.length === 1 ? rows[0] : null);
        const runPack = run
          ? snappedFor.find((x) => x.row.userName === run.userName && x.row.patrolType === run.patrolType)
          : null;
        const ridePath = runPack?.ridePath ?? [];
        const marker = riderRef.current;
        if (run && marker && ridePath.length >= 2) {
          const duration = animDurationMs(ridePath);
          const start = performance.now();
          const endPt = ridePath[ridePath.length - 1];
          const tick = (now: number) => {
            if (cancelled) return;
            const t = Math.min(1, (now - start) / duration);
            marker.setLatLng(interpolatePath(ridePath, t));
            if (t >= 1) {
              marker.setLatLng(endPt);
              return;
            }
            rafRef.current = window.requestAnimationFrame(tick);
          };
          rafRef.current = window.requestAnimationFrame(tick);
        } else if (run && marker && ridePath.length === 1) {
          marker.setLatLng(ridePath[0]);
        }

        const allPts = snappedFor.flatMap((x) => x.path);
        if (allPts.length >= 2) {
          const lats = allPts.map((p) => p[0]);
          const lngs = allPts.map((p) => p[1]);
          map.fitBounds(
            [
              [Math.min(...lats), Math.min(...lngs)],
              [Math.max(...lats), Math.max(...lngs)],
            ],
            { padding: [40, 40], maxZoom: 14 },
          );
          const dashedAny = snappedFor.some((x) => x.dashed);
          setOverlayStatus(
            dashedAny
              ? 'OSRM fallback · nét đứt'
              : 'OSRM · bám tuyến chính',
          );
        } else if (rows.length) {
          setOverlayStatus('OSRM fallback · nét đứt');
        }
      })();
    }, 0);

    return () => {
      cancelled = true;
      window.clearTimeout(timer);
      window.cancelAnimationFrame(rafRef.current);
    };
  }, [people, selected, selectedKey, sideTab, listType, checkIns, selectPerson, mapEpoch]);

  const history = useMemo(() => {
    if (!selected) return [];
    return selected.sessions
      .flatMap((s) =>
        mergePatrolStops(checkIns[s.id] ?? [], s.id).map((stop) => ({
          ...stop,
          sessionCode: s.code,
          sessionStatus: s.status,
        })),
      )
      .sort((a, b) => kmSortKey(a.planPointLabel) - kmSortKey(b.planPointLabel));
  }, [selected, checkIns]);

  return (
    <div
      className={`${live.page} ${viewFull ? live.full : live.dock}`}
      data-testid="rmms-gis-patrol-map-page"
      data-gis-map-page
    >
      <div className={live.app} data-gis-map-app>
        <aside
          className={`${live.side} ${live.dockOnly}`}
          data-gis-map-side
          data-collapsed={stacked && !sideBodyOpen ? 'true' : 'false'}
        >
          <GisMapSideTabs
            tabs={PATROL_TABS}
            active={sideTab}
            onSelect={onTabClick}
            stacked={stacked}
            bodyOpen={sideBodyOpen}
            onToggleBody={toggleBody}
            tabClassName={live.sideTabs}
            tabOnClassName={live.tabOn}
          />
          <div
            className={live.sideBody}
            data-gis-map-side-body
            hidden={stacked && !sideBodyOpen}
          >
            {(sideTab === 'tuan-duong' || sideTab === 'tuan-kiem') && (
              <>
                <p className={styles.personMeta}>
                  <span
                    className={styles.legendDot}
                    style={{ background: listType === 'Tuần kiểm' ? COLOR_TK : COLOR_TD }}
                  />
                  {people.length} người · {listType} · Vinh — Nghệ An
                </p>
                {people.length === 0 ? (
                  <p className={styles.empty}>Chưa có phiên {listType.toLowerCase()}</p>
                ) : (
                  people.map((row) => {
                    const key = `${row.patrolType}|${row.userName}`;
                    return (
                      <button
                        key={key}
                        type="button"
                        className={`${styles.personBtn} ${selectedKey === key ? styles.personOn : ''}`}
                        data-testid={`patrol-person-${row.userName}`}
                        onClick={() => selectPerson(row)}
                      >
                        <div className={styles.personName}>{row.userName}</div>
                        <div className={styles.personMeta}>
                          {row.jobTitle} · {row.routes.join(' · ')} · {row.sessions.length} ca
                        </div>
                        <span
                          className={`${styles.badge} ${row.status === 'Đang tuần' ? styles.badgeRun : styles.badgeDone}`}
                        >
                          {row.status}
                        </span>
                      </button>
                    );
                  })
                )}
              </>
            )}
            {sideTab === 'chi-tiet' && (
              selected ? (
                <>
                  <div className={styles.detailBlock}>
                    <h3>Họ tên</h3>
                    <p className={styles.detailName}>{selected.userName}</p>
                    <div className={styles.detailSub}>Chức vụ: {selected.jobTitle}</div>
                    <div className={styles.detailSub}>
                      {selected.patrolType} · độ phủ {selected.coverage}%
                    </div>
                    <span
                      className={`${styles.badge} ${selected.status === 'Đang tuần' ? styles.badgeRun : styles.badgeDone}`}
                    >
                      {selected.status}
                    </span>
                  </div>
                  <div className={styles.detailBlock}>
                    <h3>Danh sách tuyến đường</h3>
                    <ul className={styles.routeList}>
                      {selected.sessions.map((s) => (
                        <li key={s.id}>
                          <strong>{s.route}</strong>
                          {s.note ? ` — ${s.note}` : ''}
                          <div className={styles.detailSub}>
                            {s.code} · {s.status} · {s.checkInCount} điểm tuần
                          </div>
                        </li>
                      ))}
                    </ul>
                  </div>
                  <div className={styles.detailBlock}>
                    <h3>Lịch sử hoạt động</h3>
                    {history.length === 0 ? (
                      <p className={styles.empty}>Chưa có điểm check-in GPS</p>
                    ) : (
                      <ul className={styles.historyList}>
                        {history.map((h) => (
                          <li key={h.id}>
                            <strong>{h.planPointLabel}</strong>
                            <span
                              className={`${styles.badge} ${
                                checkInKindOf(h) === 'skipped'
                                  ? styles.badgeSkip
                                  : checkInKindOf(h) === 'pending'
                                    ? styles.badgeWait
                                    : styles.badgeOk
                              }`}
                            >
                              {checkInKindOf(h) === 'done' && h.createdAt
                                ? `${checkInStatusLabel('done')} · ${formatWhen(h.createdAt)}`
                                : checkInStatusLabel(checkInKindOf(h))}
                            </span>
                            <div className={styles.detailSub}>
                              {h.route}
                              {h.pending ? '' : ' · định vị đạt'}
                            </div>
                            <div className={styles.detailSub}>
                              GPS {h.lat.toFixed(5)}, {h.lng.toFixed(5)}
                            </div>
                          </li>
                        ))}
                      </ul>
                    )}
                  </div>
                </>
              ) : (
                <p className={styles.empty}>
                  Chọn người ở tab Tuần đường hoặc Tuần kiểm để xem họ tên, tuyến và lịch sử
                  check-in (parity mobile Chi tiết ca).
                </p>
              )
            )}
          </div>
        </aside>

        <main className={live.main} data-gis-map-main>
          <div className={`${live.statusRow} ${live.dockOnly}`}>
            <span>EPSG:4326</span>
            <input readOnly value={overlayStatus} aria-label="Overlay status" />
          </div>
          <div className={live.mapShell}>
            <div className={live.mapHost}>
              {!ready && !leafletError && (
                <div className={live.mapLoading}>Đang tải Leaflet…</div>
              )}
              {leafletError && <div className={live.mapError}>{leafletError}</div>}
              <div
                ref={mapRef}
                className={live.mapEl}
                role="application"
                aria-label="Bản đồ Tuần đường"
              />
            </div>
            <div className={live.mapBar} role="toolbar" aria-label="Lớp nền bản đồ">
              <div className={live.mapBasemaps} role="group" aria-label="Basemap">
                {CLIP_STYLE_OPTIONS.map((opt) => (
                  <button
                    key={opt.id}
                    type="button"
                    className={clipStyle === opt.id ? live.isActive : undefined}
                    data-basemap={opt.id}
                    title={opt.title}
                    aria-label={opt.title}
                    aria-pressed={clipStyle === opt.id}
                    onClick={() => {
                      setClipStyle(opt.id);
                      if (clipLayerRef.current) {
                        applyClipBasemapStyle(clipLayerRef.current, opt.id);
                      }
                    }}
                  >
                    {opt.label}
                  </button>
                ))}
              </div>
              <button
                type="button"
                className={live.fitBtn}
                data-action="locate-me"
                title={MY_LOCATION_TITLE}
                aria-label={MY_LOCATION_TITLE}
                aria-busy={locating}
                disabled={locating}
                onClick={locateMe}
              >
                {MY_LOCATION_LABEL}
              </button>
              <button
                type="button"
                className={live.btnMapView}
                data-action="map-view-toggle"
                title={viewFull ? 'Thu về dock (mini)' : 'Phóng full map'}
                aria-label={viewFull ? 'Thu về dock' : 'Phóng full map'}
                aria-pressed={viewFull}
                onClick={() => setViewFull((v) => !v)}
              >
                <MapViewToggleIcon expanded={viewFull} className={live.mapViewIco} />
              </button>
            </div>
          </div>
        </main>
      </div>
    </div>
  );
};

export default GisPatrolMapPage;
