import { apiClient, unwrap } from '../api';
import type { BffResponse } from '../api';
import type { PatrolCheckInDto, PatrolDto, PatrolPagedResult } from './responseModel';

/** Relative to VITE_API_URL (`web-bff/api/v1`). SSOT Field: `/patrol/sessions`. */
const BASE = '/patrol/sessions';

type PagedEnvelope = {
  items?: PatrolDto[];
  totalCount?: number;
  page?: number;
  pageSize?: number;
  totalPages?: number;
};

function normalizePaged(
  raw: PagedEnvelope | PatrolDto[] | null | undefined,
): PatrolPagedResult {
  if (Array.isArray(raw)) {
    return {
      items: raw,
      totalCount: raw.length,
      page: 1,
      pageSize: raw.length || 50,
      totalPages: 1,
    };
  }
  const items = raw?.items ?? [];
  const totalCount = raw?.totalCount ?? items.length;
  const page = raw?.page ?? 1;
  const pageSize = raw?.pageSize ?? 50;
  const totalPages =
    raw?.totalPages ?? Math.max(1, Math.ceil(totalCount / Math.max(pageSize, 1)));
  return { items, totalCount, page, pageSize, totalPages };
}

export const patrolEndpoint = {
  getList: async (params?: { page?: number; pageSize?: number }) => {
    const qs = new URLSearchParams();
    qs.set('page', String(params?.page ?? 1));
    qs.set('pageSize', String(params?.pageSize ?? 200));
    const res = await apiClient.get<BffResponse<PagedEnvelope | PatrolDto[]>>(
      `${BASE}?${qs}`,
    );
    return normalizePaged(unwrap(res));
  },

  getCheckIns: async (sessionId: string) => {
    const res = await apiClient.get<BffResponse<PatrolCheckInDto[]>>(
      `${BASE}/${sessionId}/check-ins`,
    );
    return unwrap(res) ?? [];
  },
};
